if (score === total) headline = 'Perfect score! You are an n8n legend!';
else if (score >= 8) headline = 'Outstanding! You really know your n8n.';
else if (score >= 6) headline = 'Great job! Solid n8n knowledge.';
else if (score >= 4) headline = 'Nice work! You are getting there.';
else headline = 'Thanks for playing! Every workflow starts somewhere.';

const firstName = pick.name.split(/\s+/)[0] || 'there';

return [{ json: {
  status,
  title: status === 'late' ? "Time's up, " + firstName : 'Congratulations, ' + firstName + '! 🎉',
  message: status === 'late'
    ? '<b>Your answers arrived after the time limit, so they were not counted.</b><br>You scored 0 out of ' + total + '.<br><br>Thanks for taking part!'
    : '<b>You scored ' + score + ' out of ' + total + '.</b><br>' + headline +
      '<br><br>' + (feedback ? 'Thanks for sharing your feedback!' : 'Thanks for taking the quiz!'),
  participantId: pick.participantId,
  finishedAt: new Date().toISOString(),
  score: String(score),
  total: String(total),
  feedbackCell: safeCell(feedback),
  questionIds: pick.questions.map((q) => q.id).join(',') + ',' + pick.feedbackId,
} }];
